text:
{
 "summary": {
  "es": "国会《こっかい》は、国《くに》の中《なか》でいちばん上《うえ》の機関《きかん》（※憲法《けんぽう》では「国権《こっけん》の最高機関《さいこうきかん》」）で、国《くに》でただひとつ、法律《ほうりつ》をつくる機関《きかん》です。衆議院《しゅうぎいん》と参議院《さんぎいん》の、2つの議院《ぎいん》でできています。",
  "hs": "国会は「国権の最高機関」で、国の唯一《ゆいいつ》の立法機関（法律をつくる機関）です。衆議院と参議院の二院でできています。"
 },
 "blocks/0/text": {
  "es": "自分《じぶん》の給料《きゅうりょう》にかかわる税《ぜい》の法律《ほうりつ》が、国会《こっかい》でどう話《はな》し合《あ》われたかを、読《よ》むことはできる？",
  "hs": "自分の給与《きゅうよ》にかかわる税の法律が、国会でどのように議論されたかを読むことはできる？"
 },
 "blocks/1/text": {
  "es": "憲法《けんぽう》第《だい》41条《じょう》は、国会《こっかい》を「国権《こっけん》の最高機関《さいこうきかん》であつて、国《くに》の唯一《ゆいいつ》の立法機関《りっぽうきかん》」と決《き》めています。参議院《さんぎいん》は、2つのことを説明《せつめい》しています。「最高《さいこう》機関《きかん》」は、国会《こっかい》が、国《くに》の主人《しゅじん》である国民《こくみん》の考《かんが》えを、いちばん直接《ちょくせつ》にあらわしているという意味《いみ》です。「唯一《ゆいいつ》の立法機関《りっぽうきかん》」は、法律《ほうりつ》は国会《こっかい》だけがつくり、国会《こっかい》で決《き》めるだけで決《き》まるという意味《いみ》です。",
  "hs": "憲法第41条は、国会を「国権の最高機関であつて、国の唯一《ゆいいつ》の立法機関」と定めています。参議院は、「最高機関」は国会が主権者である国民の意思を最も直接に代表するという意味だと説明しています。また「唯一《ゆいいつ》の立法機関」は、法律は国会だけが制定し、国会の議決だけで確定するという意味だと説明しています。"
 },
 "blocks/2/items/0": {
  "es": "法律《ほうりつ》をつくる（第《だい》59条《じょう》）",
  "hs": "法律の制定（第59条）"
 },
 "blocks/2/items/1": {
  "es": "予算《よさん》など、国《くに》のお金《かね》について決《き》める（第《だい》60条《じょう》・第《だい》83条《じょう》〜第《だい》91条《じょう》）",
  "hs": "予算など、国の財政（お金のやりくり）に関する議決（第60条・第83条〜第91条）"
 },
 "blocks/2/items/2": {
  "es": "外国《がいこく》と条約《じょうやく》（国《くに》どうしの約束《やくそく》）を結《むす》ぶことを認《みと》める（第《だい》61条《じょう》・第《だい》73条《じょう》）",
  "hs": "条約の締結《ていけつ》（外国と条約を結ぶこと）の承認（第61条・第73条）"
 },
 "blocks/2/items/3": {
  "es": "内閣総理大臣《ないかくそうりだいじん》を指名《しめい》する（えらんで名前《なまえ》をあげること）（第《だい》67条《じょう》）",
  "hs": "内閣総理大臣の指名（第67条）"
 },
 "blocks/2/items/4": {
  "es": "憲法《けんぽう》を変《か》える案《あん》を、国民《こくみん》に出《だ》す（第《だい》96条《じょう》）",
  "hs": "憲法改正の発議（改正の案を国民に示すこと）（第96条）"
 },
 "blocks/2/items/5": {
  "es": "裁判官《さいばんかん》をさばく、弾劾裁判所《だんがいさいばんしょ》という裁判所《さいばんしょ》をつくる（第《だい》64条《じょう》）",
  "hs": "裁判官を裁く弾劾裁判所《だんがいさいばんしょ》の設置（第64条）"
 },
 "blocks/3/items/0": {
  "es": "国政調査権《こくせいちょうさけん》（国《くに》の政治《せいじ》について調《しら》べる力《ちから》）：人《ひと》に来《き》てもらって話《はなし》を聞《き》いたり、記録《きろく》を出《だ》してもらったりできる（第《だい》62条《じょう》）",
  "hs": "国政調査権（国の政治を調べる権限）：証人に来てもらい証言を求めたり、記録の提出を求めたりできる（第62条）"
 },
 "blocks/3/items/1": {
  "es": "請願《せいがん》（国《くに》へのおねがい）を受《う》け取《と》り、決《き》める（国会《こっかい》法《ほう》第《だい》79条《じょう》・第《だい》80条《じょう》）",
  "hs": "請願《せいがん》（国などへの要望）の受理と議決（国会法第79条・第80条）"
 },
 "blocks/3/items/2": {
  "es": "役員《やくいん》をえらぶこと、決《き》まりをつくること、議員《ぎいん》をばっすること（第《だい》58条《じょう》）",
  "hs": "役員の選任、規則の制定、議員の懲罰《ちょうばつ》（ルールを破った議員への罰《ばつ》）（第58条）"
 },
 "blocks/4/text": {
  "es": "衆議院《しゅうぎいん》によると、それぞれの議院《ぎいん》には、本会議《ほんかいぎ》と委員会《いいんかい》があります。憲法審査会《けんぽうしんさかい》・情報《じょうほう》監視《かんし》審査会《しんさかい》・政治倫理《せいじりんり》審査会《しんさかい》もあります。また、国会《こっかい》には、裁判官訴追委員会《さいばんかんそついいいんかい》と裁判官弾劾裁判所《さいばんかんだんがいさいばんしょ》があります。",
  "hs": "衆議院によると、各議院には本会議と委員会があり、憲法審査会《けんぽうしんさかい》・情報｜監視《かんし》審査会《しんさかい》・政治倫理《せいじりんり》審査会《しんさかい》が設けられています。また国会には、裁判官訴追委員会《さいばんかんそついいいんかい》と裁判官弾劾裁判所《さいばんかんだんがいさいばんしょ》が設けられています。"
 },
 "blocks/5/text": {
  "es": "衆議院《しゅうぎいん》と参議院《さんぎいん》の会議《かいぎ》は、公開《こうかい》（だれでも見《み》られること）が原則《げんそく》です。ひみつの会議《かいぎ》にするには、来《き》ている議員《ぎいん》の3分《ぶん》の2以上《いじょう》が賛成《さんせい》することがいります（第《だい》57条《じょう》）。会議《かいぎ》の記録《きろく》は、国会《こっかい》会議録《かいぎろく》検索《けんさく》システムで読《よ》めます。",
  "hs": "両議院の会議は公開が原則で、秘密会を開くには出席議員の3分の2以上の議決が必要です（第57条）。会議録（会議の記録）は、国会会議録｜検索《けんさく》システムで読むことができます。"
 }
}
